import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DatosPlanNegocios } from '../status-tramite/steps/paso-3-plan-negocios/datos-plan-negocios/datos-plan-negocios';
import { EmpresaForm } from '../shared/empresa-form/empresa-form';
import { EmpresaVinculadaForm } from '../shared/empresa-vinculada-form/empresa-vinculada-form'; // ← Verificar esta línea
import { Tramite } from '../../../models/tramite';
import { TramiteService } from '../../../controllers/tramite.service';
import { Empresa } from '../../../models/empresa';

@Component({
  selector: 'app-mi-empresa',
  standalone: true,
  imports: [CommonModule, EmpresaForm, DatosPlanNegocios, EmpresaVinculadaForm],
  templateUrl: './mi-empresa.html',
  styleUrl: './mi-empresa.css',
})
export class MiEmpresa implements OnInit {
  tramite?: Tramite;
  empresaBeneficiadaId?: number;
  loading = true;
  
  private readonly tramiteService = inject(TramiteService);
  
  async ngOnInit() {
    this.loading = true;
    this.tramite = await this.tramiteService.getCurrentTramite(['empresa','datosVinculacion']);
    this.loading = false;
  
    if(this.tramite?.datos_vinculacion?.empresa_solicitante_id){
      this.empresaBeneficiadaId = this.tramite?.datos_vinculacion?.empresa_solicitante_id;
    }else{
      this.empresaBeneficiadaId = this.tramite?.empresa_id || undefined;
    }
  }

  empresaGuardada(empresa: Empresa) {
    if (!this.tramite) return;
    this.tramiteService.fastUpdate(this.tramite, { empresa_id: empresa.id });
    this.empresaBeneficiadaId = empresa.id;
  }
  
  empresaVinculadaGuardada(empresa: Empresa) {
    if (!this.tramite) return;
    this.tramiteService.fastUpdate(this.tramite, { empresa_vinculada_id: empresa.id });
  }

  onEmpresaBeneficiadaChange(event: Event) {
    const select = event.target as HTMLSelectElement;
    this.empresaBeneficiadaId = Number(select.value);
  }
  datosVinculacionCargados(empresaSolicitanteId: number) {
     this.empresaBeneficiadaId = empresaSolicitanteId;
  }
}