import { Component, EventEmitter, inject, Input, Output, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators, AbstractControl } from '@angular/forms';
import { TramiteAnexoEmpleoIndirecto } from '../../../../models/tramite-anexo-empleo-indirecto';
import { TramiteAnexoEmpleoIndirectoService } from '../../../../controllers/tramite-anexo-empleo-indirecto.service';

@Component({
  selector: 'app-tramite-anexo-empleos-indirectos',
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './tramite-anexo-empleos-indirectos.html',
  styleUrl: './tramite-anexo-empleos-indirectos.css',
})
export class TramiteAnexoEmpleosIndirectos implements OnInit {
  @Input() tramiteId!: number;
  @Input() tramiteAnexoEmpleoIndirecto?: TramiteAnexoEmpleoIndirecto;
  @Output() tramiteAnexoEmpleoIndirectoChange = new EventEmitter<TramiteAnexoEmpleoIndirecto>();

  form: FormGroup = inject(FormBuilder).group({
    tramite_id: [null, Validators.required],
    numero_empleos_generados: [0, [Validators.required, Validators.min(0)]],
    descripcion: ['', Validators.required],
    origen_empresa_proveedora: ['', Validators.required],
    tipo_proveeduria: ['', Validators.required],
  });

  isEditMode = false;
  loading = false;
  submitted = false;

  private tramiteAnexoEmpleoIndirectoService = inject(TramiteAnexoEmpleoIndirectoService);

  async ngOnInit(): Promise<void> {
    this.isEditMode = !!this.tramiteAnexoEmpleoIndirecto?.id;

    if (this.tramiteId) {
      this.form.patchValue({ tramite_id: this.tramiteId });
    }

    if (this.isEditMode && this.tramiteAnexoEmpleoIndirecto) {
      await this.loadData();
    }
  }

  private async loadData(): Promise<void> {
    if (!this.tramiteAnexoEmpleoIndirecto) return;

    this.loading = true;
    this.form.patchValue(this.tramiteAnexoEmpleoIndirecto);
    this.loading = false;
  }

  get f(): Record<string, AbstractControl> {
    return this.form.controls;
  }

  async onSubmit(): Promise<void> {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const formData = this.form.value;
    let result: TramiteAnexoEmpleoIndirecto | undefined;

    if (this.isEditMode && this.tramiteAnexoEmpleoIndirecto) {
      await this.tramiteAnexoEmpleoIndirectoService.update(this.tramiteAnexoEmpleoIndirecto.id, formData);
      result = {
        ...this.tramiteAnexoEmpleoIndirecto,
        ...formData
      };
    } else {
      result = await this.tramiteAnexoEmpleoIndirectoService.new(formData);
    }

    this.submitted = true;
    this.tramiteAnexoEmpleoIndirectoChange.emit(result);
  }

  resetForm(): void {
    this.form.reset();
    this.submitted = false;
    if (this.tramiteId) {
      this.form.patchValue({ tramite_id: this.tramiteId });
    }
  }
}
