import { Component, EventEmitter, inject, Input, OnInit, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators, AbstractControl } from '@angular/forms';
import { TramiteAnexoDiversificacionMercadosService } from '../../../../controllers/tramite-anexo-diversificacion-mercados.service';
import { TramiteAnexoDiversificacionMercados } from '../../../../models/tramite-anexo-diversificacion-mercados';
import { TramiteService } from '../../../../controllers/tramite.service';

@Component({
  selector: 'app-tramite-anexo-diversificacion-mercados-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './tramite-anexo-diversificacion-mercados-form.html',
  styleUrl: './tramite-anexo-diversificacion-mercados-form.css',
})
export class TramiteAnexoDiversificacionMercadosForm implements OnInit {
  @Input() tramiteId?: number;
  @Input() tramiteAnexoDiversificacionMercados?: TramiteAnexoDiversificacionMercados;
  @Output() tramiteAnexoDiversificacionMercadosChange = new EventEmitter<TramiteAnexoDiversificacionMercados>();
  @Output() saved = new EventEmitter<TramiteAnexoDiversificacionMercados>();
  @Output() canceled = new EventEmitter<void>();

  form: FormGroup = inject(FormBuilder).group({
    tramite_id: [null, Validators.required],
    produccion_total_unidades: [null, [Validators.min(0)]],
    produccion_total_moneda: [null as 'MXN' | 'USD' | null],
    nacional_porc: [0, [Validators.min(0), Validators.max(100)]],
    extranjero_porc: [0, [Validators.min(0), Validators.max(100)]],
    lugares_y_procedimientos_distribucion: ['', Validators.required],
  });

  isEditMode = false;
  loading = false;
  submitted = false;

  private fb = inject(FormBuilder);
  private tramiteAnexoDiversificacionMercadosService = inject(TramiteAnexoDiversificacionMercadosService);
  private tramiteService = inject(TramiteService);

  async ngOnInit(): Promise<void> {
    if (!this.tramiteId) {
      const tramite = await this.tramiteService.getCurrentTramite(['anexoMercados']);
      this.tramiteAnexoDiversificacionMercados = tramite?.anexo_mercados
      if (tramite) {
        this.tramiteId = tramite.id;
      }
    }

    this.isEditMode = !!this.tramiteAnexoDiversificacionMercados?.id;

    if (this.tramiteId) {
      this.form.patchValue({ tramite_id: this.tramiteId });
    }

    if (this.isEditMode && this.tramiteAnexoDiversificacionMercados) {
      await this.loadData();
    }
  }

  private async loadData(): Promise<void> {
    if (!this.tramiteAnexoDiversificacionMercados) return;

    this.loading = true;
    this.form.patchValue(this.tramiteAnexoDiversificacionMercados);
    this.loading = false;
  }

  get f(): Record<string, AbstractControl> {
    return this.form.controls;
  }

  get totalPorcentaje(): number {
    const nacional = this.f['nacional_porc'].value || 0;
    const extranjero = this.f['extranjero_porc'].value || 0;
    return nacional + extranjero;
  }

  async onSubmit(): Promise<void> {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const formData = this.form.value;
    let result: TramiteAnexoDiversificacionMercados | undefined;

    if (this.isEditMode && this.tramiteAnexoDiversificacionMercados) {
      await this.tramiteAnexoDiversificacionMercadosService.update(this.tramiteAnexoDiversificacionMercados.id, formData);
      result = {
        ...this.tramiteAnexoDiversificacionMercados,
        ...formData
      };
    } else {
      result = await this.tramiteAnexoDiversificacionMercadosService.new(formData);
    }

    this.submitted = true;
    this.saved.emit(result);
    this.tramiteAnexoDiversificacionMercadosChange.emit(result);
  }

  onCancel(): void {
    this.canceled.emit();
  }

  resetForm(): void {
    this.form.reset({
      tramite_id: this.tramiteId,
      produccion_total_unidades: null,
      produccion_total_moneda: null,
      nacional_porc: 0,
      extranjero_porc: 0,
      lugares_y_procedimientos_distribucion: '',
    });
    this.submitted = false;
  }

  get titulo(): string {
    return this.isEditMode ? 'Editar' : 'Registrar';
  }

  get textoBoton(): string {
    return this.isEditMode ? 'Actualizar' : 'Guardar';
  }
}
