import { Component, EventEmitter, inject, Input, OnInit, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators, AbstractControl } from '@angular/forms';
import { TramiteAnexoPrestracionesService } from '../../../../controllers/tramite-anexo-prestraciones.service';
import { TramiteAnexoPrestraciones } from '../../../../models/tramite-anexo-prestraciones';
import { TramiteService } from '../../../../controllers/tramite.service';

@Component({
  selector: 'app-tramite-anexo-prestaciones-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './tramite-anexo-prestaciones-form.html',
  styleUrl: './tramite-anexo-prestaciones-form.css',
})
export class TramiteAnexoPrestacionesForm implements OnInit {
  @Input() tramiteId?: number;
  @Input() tramiteAnexoPrestraciones?: TramiteAnexoPrestraciones;
  @Output() tramiteAnexoPrestracionesChange = new EventEmitter<TramiteAnexoPrestraciones>();
  @Output() saved = new EventEmitter<TramiteAnexoPrestraciones>();
  @Output() canceled = new EventEmitter<void>();

  form: FormGroup = inject(FormBuilder).group({
    tramite_id: [null, Validators.required],
    comedor_costo: [0, [Validators.min(0)]],
    transporte_costo: [0, [Validators.min(0)]],
    guarderia_costo: [0, [Validators.min(0)]],
    servicios_sin_costo: [''],
    moneda: ['MXN', Validators.required],
  });

  isEditMode = false;
  loading = false;
  submitted = false;

  private fb = inject(FormBuilder);
  private tramiteAnexoPrestracionesService = inject(TramiteAnexoPrestracionesService);
  private tramiteService = inject(TramiteService);

  async ngOnInit(): Promise<void> {
    if (!this.tramiteId) {
      const tramite = await this.tramiteService.getCurrentTramite(['anexoPrestaciones']);
      this.tramiteAnexoPrestraciones = tramite?.anexo_prestaciones;
      if (tramite) {
        this.tramiteId = tramite.id;
      }
    }

    this.isEditMode = !!this.tramiteAnexoPrestraciones?.id;

    if (this.tramiteId) {
      this.form.patchValue({ tramite_id: this.tramiteId });
    }

    if (this.isEditMode && this.tramiteAnexoPrestraciones) {
      await this.loadData();
    }
  }

  private async loadData(): Promise<void> {
    if (!this.tramiteAnexoPrestraciones) return;

    this.loading = true;
    this.form.patchValue(this.tramiteAnexoPrestraciones);
    this.loading = false;
  }

  get f(): Record<string, AbstractControl> {
    return this.form.controls;
  }

  async onSubmit(): Promise<void> {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const formData = this.form.value;
    let result: TramiteAnexoPrestraciones | undefined;

    if (this.isEditMode && this.tramiteAnexoPrestraciones) {
      await this.tramiteAnexoPrestracionesService.update(this.tramiteAnexoPrestraciones.id, formData);
      result = {
        ...this.tramiteAnexoPrestraciones,
        ...formData
      };
    } else {
      result = await this.tramiteAnexoPrestracionesService.new(formData);
    }

    this.submitted = true;
    this.saved.emit(result);
    this.tramiteAnexoPrestracionesChange.emit(result);
  }

  onCancel(): void {
    this.canceled.emit();
  }

  resetForm(): void {
    this.form.reset({
      tramite_id: this.tramiteId,
      comedor_costo: 0,
      transporte_costo: 0,
      guarderia_costo: 0,
      servicios_sin_costo: '',
      moneda: 'MXN',
    });
    this.submitted = false;
  }

  get titulo(): string {
    return this.isEditMode ? 'Editar' : 'Registrar';
  }

  get textoBoton(): string {
    return this.isEditMode ? 'Actualizar' : 'Guardar';
  }
}