import { Component, EventEmitter, inject, Input, OnInit, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators, AbstractControl, ValidationErrors } from '@angular/forms';
import { TramiteAnexoOrigenInversionService } from '../../../../controllers/tramite-anexo-origen-inversion.service';
import { TramiteAnexoOrigenInversion } from '../../../../models/tramite-anexo-origen-inversion';
import { TramiteService } from '../../../../controllers/tramite.service';

@Component({
  selector: 'app-tramite-anexo-origen-inversion-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './tramite-anexo-origen-inversion-form.html',
  styleUrl: './tramite-anexo-origen-inversion-form.css',
})
export class TramiteAnexoOrigenInversionForm implements OnInit {
  @Input() tramiteId?: number;
  @Input() tramiteAnexoOrigenInversion?: TramiteAnexoOrigenInversion;
  @Output() tramiteAnexoOrigenInversionChange = new EventEmitter<TramiteAnexoOrigenInversion>();
  @Output() saved = new EventEmitter<TramiteAnexoOrigenInversion>();
  @Output() canceled = new EventEmitter<void>();

  form: FormGroup = inject(FormBuilder).group({
    tramite_id: [null, Validators.required],
    extranjera_porc: [null, [Validators.min(0), Validators.max(100)]],
    nacional_porc: [null, [Validators.min(0), Validators.max(100)]],
    local_porc: [null, [Validators.min(0), Validators.max(100)]],
    lugar_origen: [''],
  }, { validators: TramiteAnexoOrigenInversionForm.validarTotalPorcentajes });

  isEditMode = false;
  loading = false;
  submitted = false;

  private fb = inject(FormBuilder);
  private tramiteAnexoOrigenInversionService = inject(TramiteAnexoOrigenInversionService);
  private tramiteService = inject(TramiteService);

  async ngOnInit(): Promise<void> {
    if (!this.tramiteId) {
      const tramite = await this.tramiteService.getCurrentTramite(['anexoOrigenInversion']);
      this.tramiteAnexoOrigenInversion = tramite?.anexo_origen_inversion;
      if (tramite) {
        this.tramiteId = tramite.id;
      }
    }

    this.isEditMode = !!this.tramiteAnexoOrigenInversion?.id;

    if (this.tramiteId) {
      this.form.patchValue({ tramite_id: this.tramiteId });
    }

    this.form.get('extranjera_porc')?.valueChanges.subscribe(() => {
      this.form.updateValueAndValidity({ emitEvent: false });
    });

    this.form.get('nacional_porc')?.valueChanges.subscribe(() => {
      this.form.updateValueAndValidity({ emitEvent: false });
    });

    this.form.get('local_porc')?.valueChanges.subscribe(() => {
      this.form.updateValueAndValidity({ emitEvent: false });
    });

    if (this.isEditMode && this.tramiteAnexoOrigenInversion) {
      await this.loadData();
    }
  }

  private async loadData(): Promise<void> {
    if (!this.tramiteAnexoOrigenInversion) return;

    this.loading = true;
    this.form.patchValue(this.tramiteAnexoOrigenInversion);
    this.loading = false;
  }

  get f(): Record<string, AbstractControl> {
    return this.form.controls;
  }

  static validarTotalPorcentajes(control: AbstractControl): ValidationErrors | null {
    const extranjera = control.get('extranjera_porc')?.value;
    const nacional = control.get('nacional_porc')?.value;
    const local = control.get('local_porc')?.value;

    const total = (extranjera || 0) + (nacional || 0) + (local || 0);

    if (total > 100) {
      return { totalExcedido: { total } };
    }

    return null;
  }

  get showLugarOrigen(): boolean {
    const extranjera = this.form.get('extranjera_porc')?.value;
    const nacional = this.form.get('nacional_porc')?.value;
    return (extranjera && extranjera > 0) || (nacional && nacional > 0);
  }

  get totalPorcentajes(): number {
    const extranjera = this.form.get('extranjera_porc')?.value || 0;
    const nacional = this.form.get('nacional_porc')?.value || 0;
    const local = this.form.get('local_porc')?.value || 0;
    return extranjera + nacional + local;
  }

  get totalExcedido(): boolean {
    return this.totalPorcentajes > 100;
  }

  get lugarOrigenRequired(): boolean {
    const control = this.form.get('lugar_origen');
    if (this.showLugarOrigen) {
      control?.addValidators([Validators.required]);
      control?.updateValueAndValidity();
    } else {
      control?.removeValidators([Validators.required]);
      control?.updateValueAndValidity();
    }
    return this.showLugarOrigen;
  }

  async onSubmit(): Promise<void> {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const formData = this.form.value;
    let result: TramiteAnexoOrigenInversion | undefined;

    if (this.isEditMode && this.tramiteAnexoOrigenInversion) {
      await this.tramiteAnexoOrigenInversionService.update(this.tramiteAnexoOrigenInversion.id, formData);
      result = {
        ...this.tramiteAnexoOrigenInversion,
        ...formData
      };
    } else {
      result = await this.tramiteAnexoOrigenInversionService.new(formData);
    }

    if (!result) {
      return;
    }

    this.submitted = true;
    this.saved.emit(result);
    this.tramiteAnexoOrigenInversionChange.emit(result);
  }

  onCancel(): void {
    this.canceled.emit();
  }

  resetForm(): void {
    const tramiteId = this.tramiteId || this.form.get('tramite_id')?.value;
    this.form.reset({
      tramite_id: tramiteId,
      extranjera_porc: null,
      nacional_porc: null,
      local_porc: null,
      lugar_origen: '',
    });
    this.submitted = false;
  }

  get titulo(): string {
    return this.isEditMode ? 'Editar' : 'Nuevo';
  }

  get textoBoton(): string {
    return this.isEditMode ? 'Actualizar' : 'Guardar';
  }
}
