import { Component, computed, inject, OnDestroy, OnInit, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Tramite } from '../../../../models/tramite';
import { TramiteAnexoInversionTecnologia } from '../../../../models/tramite-anexo-inversion-tecnologia';
import { TramiteService } from '../../../../controllers/tramite.service';
import { TramiteAnexoInversionTecnologiaService } from '../../../../controllers/tramite-anexo-inversion-tecnologia.service';
import { TramiteAnexoInversionTecnologiaTotalService } from '../../../../controllers/tramite-anexo-inversion-tecnologia-total.service';
import { UtilsService } from '../../../../services/utils.service';
import { VanillaDialogService } from '../../../../services/vanilla-dialog/vanilla-dialog.service';
import { Subject, debounceTime, takeUntil, filter, firstValueFrom } from 'rxjs';
import { TramiteAnexoInversionTecnologiaForm } from "../tramite-anexo-inversion-tecnologia-form/tramite-anexo-inversion-tecnologia-form";

interface Totales {
  monto: number;
  porcentaje: number;
}

@Component({
  selector: 'app-tramite-anexo-inversiones-tecnologia',
  imports: [
    CommonModule,
    TramiteAnexoInversionTecnologiaForm
],
  templateUrl: './tramite-anexo-inversiones-tecnologia.html',
  styleUrl: './tramite-anexo-inversiones-tecnologia.css',
})
export class TramiteAnexoInversionesTecnologia implements OnInit, OnDestroy {
  tramite = signal<Tramite | undefined>(undefined);
  anexosInversionesTecnologia = signal<TramiteAnexoInversionTecnologia[]>([]);
  showFormulario = signal(false);
  editingItem = signal<TramiteAnexoInversionTecnologia | undefined>(undefined);
  loading = signal(false);
  ventasAnuales = signal<number | undefined>(undefined);

  totalesGenerales = computed(() => this.calcularTotalesGenerales());
  importeEnLetra = computed(() => this.getImporteEnLetra());

  private tramiteService = inject(TramiteService);
  private tramiteAnexoInversionTecnologiaService = inject(TramiteAnexoInversionTecnologiaService);
  private tramiteAnexoInversionTecnologiaTotalService = inject(TramiteAnexoInversionTecnologiaTotalService);
  private utilsService = inject(UtilsService);
  private dialog = inject(VanillaDialogService);
  private ventasSubject = new Subject<number>();
  private destroy$ = new Subject<void>();

  async ngOnInit(): Promise<void> {
    this.loading.set(true);
    this.tramite.set(await this.tramiteService.getCurrentTramite(['anexosInversionTecnologia']));
    const tramite = this.tramite();
    if (tramite?.anexos_inversion_tecnologia) {
      this.anexosInversionesTecnologia.set(tramite.anexos_inversion_tecnologia);
    }

    const ventasTotales = await this.tramiteAnexoInversionTecnologiaTotalService.all({
      conditionals: { tramite_id: tramite?.id },
      loader: false
    });
    if (ventasTotales && ventasTotales.length > 0) {
      this.ventasAnuales.set(ventasTotales[0].monto);
    } else {
      this.ventasAnuales.set(0);
    }

    this.ventasSubject
      .pipe(
        debounceTime(3000),
        takeUntil(this.destroy$)
      )
      .subscribe(monto => this.guardarVentas(monto));

    this.loading.set(false);
  }

  async guardarVentas(monto: number): Promise<void> {
    const tramite = this.tramite();
    if (!tramite?.id) return;

    const ventasTotales = await this.tramiteAnexoInversionTecnologiaTotalService.all({
      conditionals: { tramite_id: tramite.id },
      loader: false
    });

    if (ventasTotales && ventasTotales.length > 0) {
      await this.tramiteAnexoInversionTecnologiaTotalService.update(ventasTotales[0].id, {
        tramite_id: tramite.id,
        monto,
        moneda: 'MXN'
      });
    } else {
      await this.tramiteAnexoInversionTecnologiaTotalService.new({
        tramite_id: tramite.id,
        monto,
        moneda: 'MXN'
      });
    }
  }

  onVentasChange(event: Event): void {
    const target = event.target as HTMLInputElement;
    const valor = target.value ? parseFloat(target.value) : 0;
    this.ventasAnuales.set(valor);
    this.ventasSubject.next(valor);
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  private calcularTotalesGenerales(): Totales {
    const anexos = this.anexosInversionesTecnologia();
    const monto = anexos.reduce((sum, r) => sum + (+(r.monto || 0)), 0);
    const ventas = this.ventasAnuales() || 0;
    const porcentaje = ventas > 0 ? (monto / ventas) * 100 : 0;

    return {
      monto,
      porcentaje
    };
  }

  getImporteEnLetra(): string {
    const ventas = this.ventasAnuales() || 0;
    return this.utilsService.numeroLetra(ventas);
  }

  abrirFormulario(item?: TramiteAnexoInversionTecnologia): void {
    this.editingItem.set(item);
    this.showFormulario.set(true);
  }

  cerrarFormulario(): void {
    this.showFormulario.set(false);
    this.editingItem.set(undefined);
  }

  async onGuardar(item: TramiteAnexoInversionTecnologia): Promise<void> {
    const currentAnexos = this.anexosInversionesTecnologia();
    const editing = this.editingItem();

    if (editing?.id) {
      const index = currentAnexos.findIndex(a => a.id === editing.id);
      if (index !== -1) {
        const nuevosAnexos = [...currentAnexos];
        nuevosAnexos[index] = item;
        this.anexosInversionesTecnologia.set(nuevosAnexos);
      }
    } else {
      this.anexosInversionesTecnologia.set([...currentAnexos, item]);
    }

    this.cerrarFormulario();
  }

  async onEliminar(id: number): Promise<void> {
    const confirmacion = await firstValueFrom(
      this.dialog.show({
        title: 'Eliminar inversión en tecnología',
        body: '¿Está seguro de eliminar este registro de inversión en tecnología?',
        tipo: 'danger',
        respYes: 'Eliminar',
        respNo: 'Cancelar'
      }).pipe(filter(r => !!r))
    );
    if (!confirmacion.closedByAgree) return;

    const result = await this.tramiteAnexoInversionTecnologiaService.switch(id);
    if (result) {
      const currentAnexos = this.anexosInversionesTecnologia();
      this.anexosInversionesTecnologia.set(currentAnexos.filter(a => a.id !== id));
    }
  }

  getPorcentaje(registro: TramiteAnexoInversionTecnologia): number {
    const ventas = this.ventasAnuales() || 0;
    if (ventas === 0) return 0;
    return (+(registro.monto || 0) / ventas) * 100;
  }
}
