import { Component, EventEmitter, inject, Input, Output, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators, AbstractControl } from '@angular/forms';
import { TramiteAnexoEmpleoService } from '../../../../controllers/tramite-anexo-empleo.service';
import { TramiteAnexoEmpleo, TramiteNivel } from '../../../../models/tramite-anexo-empleo';

type Moneda = 'MXN' | 'USD';

@Component({
  selector: 'app-tramite-anexo-empleos-directos',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './tramite-anexo-empleos-directos.html',
  styleUrl: './tramite-anexo-empleos-directos.css',
})
export class TramiteAnexoEmpleosDirectos implements OnInit {
  @Input() tramiteId !: number;
  @Input() tramiteAnexoEmpleo ?: TramiteAnexoEmpleo;
  @Output() tramiteAnexoEmpleoChange = new EventEmitter<TramiteAnexoEmpleo>();

  form: FormGroup = inject(FormBuilder).group({
    tramite_id: [null, Validators.required],
    nivel: ['', Validators.required],
    nivel_otro: [''],
    empleos_existentes: [0, [Validators.required, Validators.min(0)]],
    empleos_nuevos: [0, [Validators.required, Validators.min(0)]],
    sueldo_promedio_diario_existente: [null, [Validators.min(0)]],
    sueldo_promedio_diario_nuevo: [null, [Validators.min(0)]],
    moneda: ['MXN', Validators.required],
  });

  isEditMode = false;
  loading = false;
  submitted = false;

  nivelOptions: { value: TramiteNivel; label: string }[] = [
    { value: 'DIRECCION', label: 'Dirección' },
    { value: 'ADMINISTRACION', label: 'Administración' },
    { value: 'SUPERVISION', label: 'Supervisión' },
    { value: 'PRODUCCION', label: 'Producción' },
    { value: 'OTRO', label: 'Otro' },
  ];

  monedaOptions: { value: Moneda; label: string }[] = [
    { value: 'MXN', label: 'MXN - Pesos Mexicanos' },
    { value: 'USD', label: 'USD - Dólares Americanos' },
  ];

  private fb = inject(FormBuilder);
  private tramiteAnexoEmpleoService = inject(TramiteAnexoEmpleoService);

  async ngOnInit(): Promise<void> {
    this.isEditMode = !!this.tramiteAnexoEmpleo?.id;

    if (this.tramiteId) {
      this.form.patchValue({ tramite_id: this.tramiteId });
    }

    if (this.isEditMode && this.tramiteAnexoEmpleo) {
      await this.loadData();
    }
  }

  private async loadData(): Promise<void> {
    if (!this.tramiteAnexoEmpleo) return;

    this.loading = true;
    this.form.patchValue(this.tramiteAnexoEmpleo);
    this.loading = false;
  }

  get f(): Record<string, AbstractControl> {
    return this.form.controls;
  }

  get showNivelOtro(): boolean {
    return this.form.get('nivel')?.value === 'OTRO';
  }

  async onSubmit(): Promise<void> {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const formData = this.form.value;
    let result: TramiteAnexoEmpleo | undefined;

    if (this.isEditMode && this.tramiteAnexoEmpleo) {
      await this.tramiteAnexoEmpleoService.update(this.tramiteAnexoEmpleo.id, formData);
      result = {
        ...this.tramiteAnexoEmpleo,
        ...formData
      };
    } else {
      result = await this.tramiteAnexoEmpleoService.new(formData);
    }

    this.submitted = true;
    this.tramiteAnexoEmpleoChange.emit(result);
  }

  resetForm(): void {
    this.form.reset();
    this.submitted = false;
    if (this.tramiteId) {
      this.form.patchValue({ tramite_id: this.tramiteId });
    }
  }
}
