import { Component, EventEmitter, inject, Input, OnInit, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators, AbstractControl } from '@angular/forms';
import { TramiteAnexoEstudianteService } from '../../../../controllers/tramite-anexo-estudiante.service';
import { TramiteAnexoEstudiante } from '../../../../models/tramite-anexo-estudiante';
import { TramiteService } from '../../../../controllers/tramite.service';

@Component({
  selector: 'app-tramite-anexo-estudiante-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './tramite-anexo-estudiante-form.html',
  styleUrl: './tramite-anexo-estudiante-form.css',
})
export class TramiteAnexoEstudianteForm implements OnInit {
  @Input() tramiteId?: number;
  @Input() tramiteAnexoEstudiante?: TramiteAnexoEstudiante;
  @Output() tramiteAnexoEstudianteChange = new EventEmitter<TramiteAnexoEstudiante>();
  @Output() saved = new EventEmitter<TramiteAnexoEstudiante>();
  @Output() canceled = new EventEmitter<void>();

  form: FormGroup = inject(FormBuilder).group({
    tramite_id: [null, Validators.required],
    numero_estudiantes_a_integrar: [0, [Validators.required, Validators.min(0)]],
    carreras_que_pertenecen: ['', Validators.required],
    instrumento_que_acredita_fomalidad: ['', Validators.required],
  });

  isEditMode = false;
  loading = false;
  submitted = false;

  private fb = inject(FormBuilder);
  private tramiteAnexoEstudianteService = inject(TramiteAnexoEstudianteService);
  private tramiteService = inject(TramiteService);

  async ngOnInit(): Promise<void> {
    if (!this.tramiteId) {
      const tramite = await this.tramiteService.getCurrentTramite(['anexoEstudiante']);
      this.tramiteAnexoEstudiante = tramite?.anexo_estudiante
      if (tramite) {
        this.tramiteId = tramite.id;
      }
    }

    this.isEditMode = !!this.tramiteAnexoEstudiante?.id;

    if (this.tramiteId) {
      this.form.patchValue({ tramite_id: this.tramiteId });
    }

    if (this.isEditMode && this.tramiteAnexoEstudiante) {
      await this.loadData();
    }
  }

  private async loadData(): Promise<void> {
    if (!this.tramiteAnexoEstudiante) return;

    this.loading = true;
    this.form.patchValue(this.tramiteAnexoEstudiante);
    this.loading = false;
  }

  get f(): Record<string, AbstractControl> {
    return this.form.controls;
  }

  async onSubmit(): Promise<void> {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const formData = this.form.value;
    let result: TramiteAnexoEstudiante | undefined;

    if (this.isEditMode && this.tramiteAnexoEstudiante) {
      await this.tramiteAnexoEstudianteService.update(this.tramiteAnexoEstudiante.id, formData);
      result = {
        ...this.tramiteAnexoEstudiante,
        ...formData
      };
    } else {
      result = await this.tramiteAnexoEstudianteService.new(formData);
    }

    this.submitted = true;
    this.saved.emit(result);
    this.tramiteAnexoEstudianteChange.emit(result);
  }

  onCancel(): void {
    this.canceled.emit();
  }

  resetForm(): void {
    this.form.reset({
      tramite_id: this.tramiteId,
      numero_estudiantes_a_integrar: 0,
      carreras_que_pertenecen: '',
      instrumento_que_acredita_fomalidad: '',
    });
    this.submitted = false;
  }

  get titulo(): string {
    return this.isEditMode ? 'Editar' : 'Registrar';
  }

  get textoBoton(): string {
    return this.isEditMode ? 'Actualizar' : 'Guardar';
  }
}
