import { Component, EventEmitter, inject, Input, OnInit, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators, AbstractControl } from '@angular/forms';
import { TramiteAnexoTecnologiaLimpiaService } from '../../../../controllers/tramite-anexo-tecnologia-limpia.service';
import { TramiteAnexoTecnologiaLimpia } from '../../../../models/tramite-anexo-tecnologia-limpia';
import { TramiteService } from '../../../../controllers/tramite.service';

@Component({
  selector: 'app-tramite-anexo-tecnologia-limpia-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './tramite-anexo-tecnologia-limpia-form.html',
  styleUrl: './tramite-anexo-tecnologia-limpia-form.css',
})
export class TramiteAnexoTecnologiaLimpiaForm implements OnInit {
  @Input() tramiteId?: number;
  @Input() tramiteAnexoTecnologiaLimpia?: TramiteAnexoTecnologiaLimpia;
  @Output() tramiteAnexoTecnologiaLimpiaChange = new EventEmitter<TramiteAnexoTecnologiaLimpia>();
  @Output() saved = new EventEmitter<TramiteAnexoTecnologiaLimpia>();
  @Output() canceled = new EventEmitter<void>();

  form: FormGroup = inject(FormBuilder).group({
    tramite_id: [null, Validators.required],
    programa_implementado: ['', Validators.required],
    residuos_reciclados_porc: [null, [Validators.min(0), Validators.max(100)]],
  });

  isEditMode = false;
  loading = false;
  submitted = false;

  private fb = inject(FormBuilder);
  private tramiteAnexoTecnologiaLimpiaService = inject(TramiteAnexoTecnologiaLimpiaService);
  private tramiteService = inject(TramiteService);

  async ngOnInit(): Promise<void> {
    if (!this.tramiteId) {
      const tramite = await this.tramiteService.getCurrentTramite(['anexoTecnologiaLimpia']);
      this.tramiteAnexoTecnologiaLimpia = tramite?.anexo_tecnologia_limpia
      if (tramite) {
        this.tramiteId = tramite.id;
      }
    }

    this.isEditMode = !!this.tramiteAnexoTecnologiaLimpia?.id;

    if (this.tramiteId) {
      this.form.patchValue({ tramite_id: this.tramiteId });
    }

    if (this.isEditMode && this.tramiteAnexoTecnologiaLimpia) {
      await this.loadData();
    }
  }

  private async loadData(): Promise<void> {
    if (!this.tramiteAnexoTecnologiaLimpia) return;

    this.loading = true;
    this.form.patchValue(this.tramiteAnexoTecnologiaLimpia);
    this.loading = false;
  }

  get f(): Record<string, AbstractControl> {
    return this.form.controls;
  }

  async onSubmit(): Promise<void> {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const formData = this.form.value;
    let result: TramiteAnexoTecnologiaLimpia | undefined;

    if (this.isEditMode && this.tramiteAnexoTecnologiaLimpia) {
      await this.tramiteAnexoTecnologiaLimpiaService.update(this.tramiteAnexoTecnologiaLimpia.id, formData);
      result = {
        ...this.tramiteAnexoTecnologiaLimpia,
        ...formData
      };
    } else {
      result = await this.tramiteAnexoTecnologiaLimpiaService.new(formData);
    }

    this.submitted = true;
    this.saved.emit(result);
    this.tramiteAnexoTecnologiaLimpiaChange.emit(result);
  }

  onCancel(): void {
    this.canceled.emit();
  }

  resetForm(): void {
    this.form.reset({
      tramite_id: this.tramiteId,
      programa_implementado: '',
      residuos_reciclados_porc: null,
    });
    this.submitted = false;
  }

  get titulo(): string {
    return this.isEditMode ? 'Editar' : 'Registrar';
  }

  get textoBoton(): string {
    return this.isEditMode ? 'Actualizar' : 'Guardar';
  }
}
