import { Component, inject, input, output, computed, ChangeDetectionStrategy, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators, AbstractControl } from '@angular/forms';
import { TramiteAnexoProveeduriaService } from '../../../../controllers/tramite-anexo-proveeduria.service';
import { TramiteAnexoProveeduria } from '../../../../models/tramite-anexo-proveeduria';
import { TramiteService } from '../../../../controllers/tramite.service';

@Component({
  selector: 'app-tramite-anexo-proveeduria-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './tramite-anexo-proveeduria-form.html',
  styleUrl: './tramite-anexo-proveeduria-form.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class TramiteAnexoProveeduriaForm implements OnInit {
  tramiteId = input<number | undefined>(undefined);
  tramiteAnexoProveeduria = input<TramiteAnexoProveeduria | undefined>(undefined);
  tramiteAnexoProveeduriaChange = output<TramiteAnexoProveeduria>();
  saved = output<TramiteAnexoProveeduria>();
  canceled = output<void>();

  form: FormGroup = inject(FormBuilder).group({
    tramite_id: [null, Validators.required],
    proveedor: ['', Validators.required],
    insumo_producto: ['', [Validators.required, Validators.minLength(3)]],
    valor_adquisicion: [null, [Validators.required, Validators.min(0)]],
    moneda: ['MXN', Validators.required],
  });

  isEditMode = computed(() => !!this.tramiteAnexoProveeduria()?.id);
  loading = false;
  submitted = false;

  monedaOptions = ['MXN', 'USD'];

  private fb = inject(FormBuilder);
  private tramiteAnexoProveeduriaService = inject(TramiteAnexoProveeduriaService);
  private tramiteService = inject(TramiteService);

  async ngOnInit(): Promise<void> {
    let tramiteId = this.tramiteId();

    if (!tramiteId) {
      const tramite = await this.tramiteService.getCurrentTramite();
      if (tramite) {
        tramiteId = tramite.id;
      }
    }

    if (tramiteId) {
      this.form.patchValue({ tramite_id: tramiteId });
    }

    if (this.isEditMode() && this.tramiteAnexoProveeduria()) {
      await this.loadData();
    }
  }

  private async loadData(): Promise<void> {
    const data = this.tramiteAnexoProveeduria();
    if (!data) return;

    this.loading = true;
    this.form.patchValue(data);
    this.loading = false;
  }

  get f(): Record<string, AbstractControl> {
    return this.form.controls;
  }

  async onSubmit(): Promise<void> {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const formData = this.form.value;
    let result: TramiteAnexoProveeduria | undefined;

    if (this.isEditMode() && this.tramiteAnexoProveeduria()) {
      await this.tramiteAnexoProveeduriaService.update(this.tramiteAnexoProveeduria()!.id, formData);
      result = { ...this.tramiteAnexoProveeduria()!, ...formData };
    } else {
      result = await this.tramiteAnexoProveeduriaService.new(formData);
    }

    if (!result) {
      return;
    }

    this.submitted = true;
    this.saved.emit(result);
    this.tramiteAnexoProveeduriaChange.emit(result);
  }

  onCancel(): void {
    this.canceled.emit();
  }

  resetForm(): void {
    const tramiteId = this.tramiteId() || this.form.get('tramite_id')?.value;
    this.form.reset({
      tramite_id: tramiteId,
      proveedor: '',
      insumo_producto: '',
      valor_adquisicion: null,
      moneda: 'MXN',
    });
    this.submitted = false;
  }

  get titulo(): string {
    return this.isEditMode() ? 'Editar' : 'Nuevo';
  }

  get textoBoton(): string {
    return this.isEditMode() ? 'Actualizar' : 'Guardar';
  }
}
