import { Component, inject, input, output, computed, ChangeDetectionStrategy, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators, AbstractControl } from '@angular/forms';
import { TramiteAnexoInversionTecnologiaService } from '../../../../controllers/tramite-anexo-inversion-tecnologia.service';
import { TramiteAnexoInversionTecnologia } from '../../../../models/tramite-anexo-inversion-tecnologia';
import { TramiteService } from '../../../../controllers/tramite.service';

@Component({
  selector: 'app-tramite-anexo-inversion-tecnologia-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './tramite-anexo-inversion-tecnologia-form.html',
  styleUrl: './tramite-anexo-inversion-tecnologia-form.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class TramiteAnexoInversionTecnologiaForm implements OnInit {
  tramiteId = input<number | undefined>(undefined);
  tramiteAnexoInversionTecnologia = input<TramiteAnexoInversionTecnologia | undefined>(undefined);
  tramiteAnexoInversionTecnologiaChange = output<TramiteAnexoInversionTecnologia>();
  saved = output<TramiteAnexoInversionTecnologia>();
  canceled = output<void>();

  form: FormGroup = inject(FormBuilder).group({
    tramite_id: [null, Validators.required],
    concepto: ['', [Validators.required, Validators.minLength(3)]],
    monto: [null, [Validators.required, Validators.min(0)]],
  });

  isEditMode = computed(() => !!this.tramiteAnexoInversionTecnologia()?.id);
  loading = false;
  submitted = false;

  private fb = inject(FormBuilder);
  private tramiteAnexoInversionTecnologiaService = inject(TramiteAnexoInversionTecnologiaService);
  private tramiteService = inject(TramiteService);

  async ngOnInit(): Promise<void> {
    let tramiteId = this.tramiteId();

    if (!tramiteId) {
      const tramite = await this.tramiteService.getCurrentTramite();
      if (tramite) {
        tramiteId = tramite.id;
      }
    }

    if (tramiteId) {
      this.form.patchValue({ tramite_id: tramiteId });
    }

    if (this.isEditMode() && this.tramiteAnexoInversionTecnologia()) {
      await this.loadData();
    }
  }

  private async loadData(): Promise<void> {
    const data = this.tramiteAnexoInversionTecnologia();
    if (!data) return;

    this.loading = true;
    this.form.patchValue(data);
    this.loading = false;
  }

  get f(): Record<string, AbstractControl> {
    return this.form.controls;
  }

  async onSubmit(): Promise<void> {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const formData = this.form.value;
    let result: TramiteAnexoInversionTecnologia | undefined;

    if (this.isEditMode() && this.tramiteAnexoInversionTecnologia()) {
      await this.tramiteAnexoInversionTecnologiaService.update(this.tramiteAnexoInversionTecnologia()!.id, formData);
      result = { ...this.tramiteAnexoInversionTecnologia()!, ...formData };
    } else {
      result = await this.tramiteAnexoInversionTecnologiaService.new(formData);
    }

    if (!result) {
      return;
    }

    this.submitted = true;
    this.saved.emit(result);
    this.tramiteAnexoInversionTecnologiaChange.emit(result);
  }

  onCancel(): void {
    this.canceled.emit();
  }

  resetForm(): void {
    const tramiteId = this.tramiteId() || this.form.get('tramite_id')?.value;
    this.form.reset({
      tramite_id: tramiteId,
      concepto: '',
      monto: null,
    });
    this.submitted = false;
  }

  get titulo(): string {
    return this.isEditMode() ? 'Editar' : 'Nuevo';
  }

  get textoBoton(): string {
    return this.isEditMode() ? 'Actualizar' : 'Guardar';
  }
}
