import { Component, computed, inject, OnInit, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Tramite } from '../../../../models/tramite';
import { TramiteAnexoProveeduria } from '../../../../models/tramite-anexo-proveeduria';
import { TramiteAnexoProveeduriaEntidadFederativa } from '../../../../models/tramite-anexo-proveeduria-entidad-federativa';
import { TramiteService } from '../../../../controllers/tramite.service';
import { TramiteAnexoProveeduriaService } from '../../../../controllers/tramite-anexo-proveeduria.service';
import { TramiteAnexoProveeduriaEntidadFederativaService } from '../../../../controllers/tramite-anexo-proveeduria-entidad-federativa.service';
import { TramiteAnexoProveeduriaForm } from '../tramite-anexo-proveeduria-form/tramite-anexo-proveeduria-form';
import { TramiteAnexoProveeduriaOtraEntidadFederativaForm } from '../tramite-anexo-proveeduria-otra-entidad-federativa-form/tramite-anexo-proveeduria-otra-entidad-federativa-form';
import { VanillaDialogService } from '../../../../services/vanilla-dialog/vanilla-dialog.service';
import { filter, firstValueFrom } from 'rxjs';

interface Totales {
  monto: number;
}

interface MonedaGrupo {
  moneda: string;
  registros: TramiteAnexoProveeduria[];
  total: number;
}

@Component({
  selector: 'app-tramite-anexo-proveedurias',
  imports: [
    CommonModule,
    TramiteAnexoProveeduriaForm,
    TramiteAnexoProveeduriaOtraEntidadFederativaForm
  ],
  templateUrl: './tramite-anexo-proveedurias.html',
  styleUrl: './tramite-anexo-proveedurias.css',
})
export class TramiteAnexoProveedurias implements OnInit {
  tramite = signal<Tramite | undefined>(undefined);
  anexosProveeduria = signal<TramiteAnexoProveeduria[]>([]);
  anexoProveeduriaEntidadFederativa = signal<TramiteAnexoProveeduriaEntidadFederativa | undefined>(undefined);
  showFormulario = signal(false);
  showFormularioExterno = signal(false);
  editingItem = signal<TramiteAnexoProveeduria | undefined>(undefined);
  editingItemExterno = signal<TramiteAnexoProveeduriaEntidadFederativa | undefined>(undefined);
  loading = signal(false);

  anexosPorMoneda = computed(() => this.agruparPorMoneda());
  totalesGenerales = computed(() => this.calcularTotalesGenerales());

  private tramiteService = inject(TramiteService);
  private tramiteAnexoProveeduriaService = inject(TramiteAnexoProveeduriaService);
  private tramiteAnexoProveeduriaEntidadFederativaService = inject(TramiteAnexoProveeduriaEntidadFederativaService);
  private dialog = inject(VanillaDialogService);

  async ngOnInit(): Promise<void> {
    this.loading.set(true);
    this.tramite.set(await this.tramiteService.getCurrentTramite(['anexosProveeduria', 'anexoProveeduriaEntidadFederativa']));
    const tramite = this.tramite();
    if (tramite?.anexos_proveeduria) {
      this.anexosProveeduria.set(tramite.anexos_proveeduria);
    }
    if (tramite?.anexo_proveeduria_entidad_federativa) {
      this.anexoProveeduriaEntidadFederativa.set(tramite.anexo_proveeduria_entidad_federativa);
    }
    this.loading.set(false);
  }

  private agruparPorMoneda(): MonedaGrupo[] {
    const anexos = this.anexosProveeduria();
    const porMoneda = new Map<string, TramiteAnexoProveeduria[]>();

    for (const anexo of anexos) {
      if (!porMoneda.has(anexo.moneda)) {
        porMoneda.set(anexo.moneda, []);
      }
      porMoneda.get(anexo.moneda)!.push(anexo);
    }

    const resultados: MonedaGrupo[] = [];
    for (const [moneda, registros] of porMoneda) {
      const total = registros.reduce((sum, r) => sum + (+(r.valor_adquisicion || 0)), 0);
      resultados.push({ moneda, registros, total });
    }

    return resultados.sort((a, b) => a.moneda.localeCompare(b.moneda));
  }

  private calcularTotalesGenerales(): Totales {
    const anexos = this.anexosProveeduria();
    const monto = anexos.reduce((sum, r) => sum + (+(r.valor_adquisicion || 0)), 0);
    return { monto };
  }

  abrirFormulario(item?: TramiteAnexoProveeduria): void {
    this.editingItem.set(item);
    this.showFormulario.set(true);
  }

  cerrarFormulario(): void {
    this.showFormulario.set(false);
    this.editingItem.set(undefined);
  }

  async onGuardar(item: TramiteAnexoProveeduria): Promise<void> {
    const currentAnexos = this.anexosProveeduria();
    const editing = this.editingItem();

    if (editing?.id) {
      const index = currentAnexos.findIndex(a => a.id === editing.id);
      if (index !== -1) {
        const nuevosAnexos = [...currentAnexos];
        nuevosAnexos[index] = item;
        this.anexosProveeduria.set(nuevosAnexos);
      }
    } else {
      this.anexosProveeduria.set([...currentAnexos, item]);
    }

    this.cerrarFormulario();
  }

  async onEliminar(id: number): Promise<void> {
    const confirmacion = await firstValueFrom(
      this.dialog.show({
        title: 'Eliminar proveedor',
        body: '¿Está seguro de eliminar este registro de proveeduría?',
        tipo: 'danger',
        respYes: 'Eliminar',
        respNo: 'Cancelar'
      }).pipe(filter(r => !!r))
    );
    if (!confirmacion.closedByAgree) return;

    const result = await this.tramiteAnexoProveeduriaService.switch(id);
    if (result) {
      const currentAnexos = this.anexosProveeduria();
      this.anexosProveeduria.set(currentAnexos.filter(a => a.id !== id));
    }
  }

  abrirFormularioExterno(): void {
    this.editingItemExterno.set(this.anexoProveeduriaEntidadFederativa());
    this.showFormularioExterno.set(true);
  }

  cerrarFormularioExterno(): void {
    this.showFormularioExterno.set(false);
    this.editingItemExterno.set(undefined);
  }

  async onGuardarExterno(item: TramiteAnexoProveeduriaEntidadFederativa): Promise<void> {
    this.anexoProveeduriaEntidadFederativa.set(item);
    const tramite = this.tramite();
    if (tramite) {
      tramite.anexo_proveeduria_entidad_federativa = item;
    }
    this.cerrarFormularioExterno();
  }
}
