import { Component, computed, inject, OnInit, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Tramite } from '../../../../models/tramite';
import { TramiteAnexoInversion } from '../../../../models/tramite-anexo-inversion';
import { TramiteService } from '../../../../controllers/tramite.service';
import { TramiteAnexoInversionService } from '../../../../controllers/tramite-anexo-inversion.service';
import { TramiteAnexoInversionForm } from '../tramite-anexo-inversion-form/tramite-anexo-inversion-form';
import { TipoInversion, TIPO_LABELS, TIPO_ORDER } from '../constants/nombres-inversion';
import { UtilsService } from '../../../../services/utils.service';
import { VanillaDialogService } from '../../../../services/vanilla-dialog/vanilla-dialog.service';
import { filter, firstValueFrom } from 'rxjs';

interface Totales {
  montoActual: number;
  montoFuturo: number;
  montoTotal: number;
  porcentajeActual: number;
  porcentajeFuturo: number;
}

interface MonedaGrupo {
  moneda: string;
  registros: TramiteAnexoInversion[];
  totales: Totales;
}

interface TipoGrupo {
  tipo: TipoInversion;
  tipoLabel: string;
  monedas: MonedaGrupo[];
  totales: Totales;
}

interface TotalGeneralMoneda {
  moneda: string;
  totales: Totales;
}

@Component({
  selector: 'app-tramite-anexo-inversiones',
  imports: [
    CommonModule,
    TramiteAnexoInversionForm
  ],
  templateUrl: './tramite-anexo-inversiones.html',
  styleUrl: './tramite-anexo-inversiones.css',
})
export class TramiteAnexoInversiones implements OnInit {
  tramite = signal<Tramite | undefined>(undefined);
  anexosInversiones = signal<TramiteAnexoInversion[]>([]);
  showFormulario = signal(false);
  editingItem = signal<TramiteAnexoInversion | undefined>(undefined);
  loading = signal(false);

  anexosPorTipo = computed(() => this.agruparPorTipo());
  totalesGeneralesPorMoneda = computed(() => this.calcularTotalesGeneralesPorMoneda());
  totalesGenerales = computed(() => this.calcularTotalesGenerales());
  importeEnLetra = computed(() => this.getImporteEnLetra());

  private tramiteService = inject(TramiteService);
  private tramiteAnexoInversionService = inject(TramiteAnexoInversionService);
  private utilsService = inject(UtilsService);
  private dialog = inject(VanillaDialogService);

  async ngOnInit(): Promise<void> {
    this.loading.set(true);
    this.tramite.set(await this.tramiteService.getCurrentTramite(['anexosInversiones']));
    const tramite = this.tramite();
    if (tramite?.anexos_inversiones) {
      this.anexosInversiones.set(tramite.anexos_inversiones);
    }
    this.loading.set(false);
  }

  private agruparPorTipo(): TipoGrupo[] {
    const anexos = this.anexosInversiones();
    const grupos = new Map<TipoInversion, TipoGrupo>();

    for (const tipo of TIPO_ORDER) {
      grupos.set(tipo, {
        tipo,
        tipoLabel: TIPO_LABELS[tipo],
        monedas: [],
        totales: this.crearTotalesVacios()
      });
    }

    const anexosPorTipo = new Map<TipoInversion, TramiteAnexoInversion[]>();
    for (const anexo of anexos) {
      const tipo = anexo.tipo_inversion;
      if (!anexosPorTipo.has(tipo)) {
        anexosPorTipo.set(tipo, []);
      }
      anexosPorTipo.get(tipo)!.push(anexo);
    }

    for (const [tipo, registrosTipo] of anexosPorTipo) {
      const grupo = grupos.get(tipo);
      if (!grupo) continue;

      const monedasMap = new Map<string, TramiteAnexoInversion[]>();
      for (const registro of registrosTipo) {
        if (!monedasMap.has(registro.moneda)) {
          monedasMap.set(registro.moneda, []);
        }
        monedasMap.get(registro.moneda)!.push(registro);
      }

      for (const [moneda, registrosMoneda] of monedasMap) {
        grupo.monedas.push({
          moneda,
          registros: registrosMoneda,
          totales: this.calcularTotales(registrosMoneda, this.calcularTotalGeneralMonto())
        });
      }

      grupo.totales = this.calcularTotales(registrosTipo, this.calcularTotalGeneralMonto());
    }

    return Array.from(grupos.values()).filter(g => g.monedas.length > 0);
  }

  private calcularTotalesGeneralesPorMoneda(): TotalGeneralMoneda[] {
    const anexos = this.anexosInversiones();
    const porMoneda = new Map<string, TramiteAnexoInversion[]>();

    for (const anexo of anexos) {
      if (!porMoneda.has(anexo.moneda)) {
        porMoneda.set(anexo.moneda, []);
      }
      porMoneda.get(anexo.moneda)!.push(anexo);
    }

    const resultados: TotalGeneralMoneda[] = [];
    const totalGeneralMonto = this.calcularTotalGeneralMonto();
    
    for (const [moneda, registros] of porMoneda) {
      resultados.push({
        moneda,
        totales: this.calcularTotales(registros, totalGeneralMonto)
      });
    }

    return resultados;
  }

  private calcularTotalGeneralMonto(): number {
    const anexos = this.anexosInversiones();
    return anexos.reduce((sum, r) => sum + (+(r.cantidad_futura || 0) - +(r.cantidad_actual || 0)), 0);
  }

  private calcularTotalesGenerales(): Totales {
    return this.calcularTotales(this.anexosInversiones(), this.calcularTotalGeneralMonto());
  }

  private calcularTotales(registros: TramiteAnexoInversion[], totalGeneralMonto: number): Totales {
    if (registros.length === 0) {
      return this.crearTotalesVacios();
    }

    const montoActual = registros.reduce((sum, r) => sum + +(r.cantidad_actual || 0), 0);
    const montoFuturo = registros.reduce((sum, r) => sum + +(r.cantidad_futura || 0), 0);
    const montoTotal = montoFuturo - montoActual;

    const porcentajeActual = totalGeneralMonto > 0 
      ? (montoActual / totalGeneralMonto) * 100 
      : 0;
    const porcentajeFuturo = totalGeneralMonto > 0 
      ? (montoFuturo / totalGeneralMonto) * 100 
      : 0;

    return {
      montoActual,
      montoFuturo,
      montoTotal,
      porcentajeActual,
      porcentajeFuturo
    };
  }

  private crearTotalesVacios(): Totales {
    return {
      montoActual: 0,
      montoFuturo: 0,
      montoTotal: 0,
      porcentajeActual: 0,
      porcentajeFuturo: 0
    };
  }

  getImporteEnLetra(): string {
    const totales = this.totalesGenerales();
    return this.utilsService.numeroLetra(totales.montoTotal);
  }

  getTiposOcupados(): { tipo: TipoInversion; nombre: string }[] {
    return this.anexosInversiones().map(a => ({
      tipo: a.tipo_inversion,
      nombre: a.nombre
    }));
  }

  abrirFormulario(item?: TramiteAnexoInversion): void {
    this.editingItem.set(item);
    this.showFormulario.set(true);
  }

  cerrarFormulario(): void {
    this.showFormulario.set(false);
    this.editingItem.set(undefined);
  }

  async onGuardar(item: TramiteAnexoInversion): Promise<void> {
    const currentAnexos = this.anexosInversiones();
    const editing = this.editingItem();

    if (editing?.id) {
      const index = currentAnexos.findIndex(a => a.id === editing.id);
      if (index !== -1) {
        const nuevosAnexos = [...currentAnexos];
        nuevosAnexos[index] = item;
        this.anexosInversiones.set(nuevosAnexos);
      }
    } else {
      this.anexosInversiones.set([...currentAnexos, item]);
    }

    this.cerrarFormulario();
  }

  async onEliminar(id: number): Promise<void> {
    const confirmacion = await firstValueFrom(
      this.dialog.show({
        title: 'Eliminar inversión',
        body: '¿Está seguro de eliminar este registro de inversión?',
        tipo: 'danger',
        respYes: 'Eliminar',
        respNo: 'Cancelar'
      }).pipe(filter(r => !!r))
    );
    if (!confirmacion.closedByAgree) return;

    const result = await this.tramiteAnexoInversionService.switch(id);
    if (result) {
      const currentAnexos = this.anexosInversiones();
      this.anexosInversiones.set(currentAnexos.filter(a => a.id !== id));
    }
  }

  getTipoLabel(tipo: string): string {
    return TIPO_LABELS[tipo as TipoInversion] || tipo;
  }

  getTipoColor(tipo: string): string {
    const colores: Record<TipoInversion, string> = {
      'FIJA': 'primary',
      'DIFERIDA': 'success',
      'CAPITAL_TRABAJO': 'info',
      'OTROS': 'secondary'
    };
    return colores[tipo as TipoInversion] || 'secondary';
  }

  getTotal(registro: TramiteAnexoInversion): number {
    return +(registro.cantidad_futura || 0) - +(registro.cantidad_actual || 0);
  }

  getPorcentajeActual(registro: TramiteAnexoInversion): number {
    const totalGeneral = this.calcularTotalGeneralMonto();
    if (totalGeneral === 0) return 0;
    return (+(registro.cantidad_actual || 0) / totalGeneral) * 100;
  }

  getPorcentajeFuturo(registro: TramiteAnexoInversion): number {
    const totalGeneral = this.calcularTotalGeneralMonto();
    if (totalGeneral === 0) return 0;
    return (+(registro.cantidad_futura || 0) / totalGeneral) * 100;
  }
}
