import { Component, EventEmitter, inject, Input, OnInit, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators, AbstractControl } from '@angular/forms';
import { TramiteAnexoInversionService } from '../../../../controllers/tramite-anexo-inversion.service';
import { TramiteAnexoInversion } from '../../../../models/tramite-anexo-inversion';
import { TramiteService } from '../../../../controllers/tramite.service';
import { NOMBRES_INVERSION, TipoInversion } from '../constants/nombres-inversion';

@Component({
  selector: 'app-tramite-anexo-inversion-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './tramite-anexo-inversion-form.html',
  styleUrl: './tramite-anexo-inversion-form.css',
})
export class TramiteAnexoInversionForm implements OnInit {
  @Input() tramiteId?: number;
  @Input() tramiteAnexoInversion?: TramiteAnexoInversion;
  @Input() tiposOcupados: { tipo: TipoInversion; nombre: string }[] = [];
  @Output() tramiteAnexoInversionChange = new EventEmitter<TramiteAnexoInversion>();
  @Output() saved = new EventEmitter<TramiteAnexoInversion>();
  @Output() canceled = new EventEmitter<void>();

  form: FormGroup = inject(FormBuilder).group({
    tramite_id: [null, Validators.required],
    tipo_inversion: ['', Validators.required],
    nombre: ['', Validators.required],
    cantidad_actual: [null, [Validators.min(0)]],
    cantidad_futura: [null, [Validators.min(0)]],
    moneda: ['MXN', Validators.required],
  });

  isEditMode = false;
  loading = false;
  submitted = false;

  tipoInversionOptions: { value: TipoInversion; label: string }[] = [
    { value: 'FIJA', label: 'Inversión Fija' },
    { value: 'DIFERIDA', label: 'Inversión Diferida' },
    { value: 'CAPITAL_TRABAJO', label: 'Capital de Trabajo' },
    { value: 'OTROS', label: 'Otros' },
  ];

  monedaOptions = ['MXN', 'USD'];

  private fb = inject(FormBuilder);
  private tramiteAnexoInversionService = inject(TramiteAnexoInversionService);
  private tramiteService = inject(TramiteService);

  async ngOnInit(): Promise<void> {
    this.isEditMode = !!this.tramiteAnexoInversion?.id;

    if (!this.tramiteId) {
      const tramite = await this.tramiteService.getCurrentTramite();
      if (tramite) {
        this.tramiteId = tramite.id;
      }
    }

    if (this.tramiteId) {
      this.form.patchValue({ tramite_id: this.tramiteId });
    }

    if (this.isEditMode && this.tramiteAnexoInversion) {
      await this.loadData();
    }

    this.form.get('tipo_inversion')?.valueChanges.subscribe(() => {
      this.onTipoInversionChange();
    });
  }

  private async loadData(): Promise<void> {
    if (!this.tramiteAnexoInversion) return;
    this.loading = true;
    this.form.patchValue(this.tramiteAnexoInversion);
    this.loading = false;
  }

  get f(): Record<string, AbstractControl> {
    return this.form.controls;
  }

  get showTipoOtro(): boolean {
    return this.form.get('tipo_inversion')?.value === 'OTROS';
  }

  get nombreOptions(): string[] {
    const tipo = this.form.get('tipo_inversion')?.value as TipoInversion | null;
    if (!tipo) return [];
    
    const opciones = NOMBRES_INVERSION[tipo] || [];
    
    const nombresOcupados = this.tiposOcupados
      .filter(ocupado => ocupado.tipo === tipo)
      .map(ocupado => ocupado.nombre);
    
    const nombreActual = this.tramiteAnexoInversion?.nombre;
    
    return opciones.filter(opcion => 
      !nombresOcupados.includes(opcion) || opcion === nombreActual
    );
  }

  onTipoInversionChange(): void {
    const tipo = this.form.get('tipo_inversion')?.value as TipoInversion | null;
    if (tipo && tipo === 'OTROS') {
      this.form.get('nombre')?.setValue('');
    } else {
      this.form.get('nombre')?.setValue('');
    }
  }

  async onSubmit(): Promise<void> {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const formData = this.form.value;
    let result: TramiteAnexoInversion | undefined;

    if (this.isEditMode && this.tramiteAnexoInversion) {
      await this.tramiteAnexoInversionService.update(this.tramiteAnexoInversion.id, formData);
      result = { ...this.tramiteAnexoInversion, ...formData };
    } else {
      result = await this.tramiteAnexoInversionService.new(formData);
    }

    if(!result){
      return;
    }

    this.submitted = true;
    this.saved.emit(result);
    this.tramiteAnexoInversionChange.emit(result);
  }

  onCancel(): void {
    this.canceled.emit();
  }

  resetForm(): void {
    this.form.reset({
      tramite_id: this.tramiteId,
      tipo_inversion: '',
      nombre: '',
      cantidad_actual: null,
      cantidad_futura: null,
      moneda: 'MXN',
    });
    this.submitted = false;
  }

  get titulo(): string {
    return this.isEditMode ? 'Editar' : 'Nueva';
  }

  get textoBoton(): string {
    return this.isEditMode ? 'Actualizar' : 'Guardar';
  }
}
