import { Component, EventEmitter, inject, Input, OnInit, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators, AbstractControl } from '@angular/forms';
import { TramiteAnexoProveeduriaEntidadFederativaService } from '../../../../controllers/tramite-anexo-proveeduria-entidad-federativa.service';
import { TramiteAnexoProveeduriaEntidadFederativa } from '../../../../models/tramite-anexo-proveeduria-entidad-federativa';
import { TramiteService } from '../../../../controllers/tramite.service';

@Component({
  selector: 'app-tramite-anexo-proveeduria-otra-entidad-federativa-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './tramite-anexo-proveeduria-otra-entidad-federativa-form.html',
  styleUrl: './tramite-anexo-proveeduria-otra-entidad-federativa-form.css',
})
export class TramiteAnexoProveeduriaOtraEntidadFederativaForm implements OnInit {
  @Input() tramiteId?: number;
  @Input() tramiteAnexoProveeduriaOtraEntidadFederativa?: TramiteAnexoProveeduriaEntidadFederativa;
  @Output() tramiteAnexoProveeduriaOtraEntidadFederativaChange = new EventEmitter<TramiteAnexoProveeduriaEntidadFederativa>();
  @Output() saved = new EventEmitter<TramiteAnexoProveeduriaEntidadFederativa>();
  @Output() canceled = new EventEmitter<void>();

  form: FormGroup = inject(FormBuilder).group({
    tramite_id: [null, Validators.required],
    total_proveedores_externos: [0, [Validators.required, Validators.min(0)]],
    lugar_adquisicion: [''],
  });

  isEditMode = false;
  loading = false;
  submitted = false;

  private fb = inject(FormBuilder);
  private tramiteAnexoProveeduriaEntidadFederativaService = inject(TramiteAnexoProveeduriaEntidadFederativaService);
  private tramiteService = inject(TramiteService);

  async ngOnInit(): Promise<void> {
    if (!this.tramiteId) {
      const tramite = await this.tramiteService.getCurrentTramite(['anexoProveeduriaEntidadFederativa']);
      this.tramiteAnexoProveeduriaOtraEntidadFederativa = tramite?.anexo_proveeduria_entidad_federativa;
      if (tramite) {
        this.tramiteId = tramite.id;
      }
    }

    this.isEditMode = !!this.tramiteAnexoProveeduriaOtraEntidadFederativa?.id;

    if (this.tramiteId) {
      this.form.patchValue({ tramite_id: this.tramiteId });
    }

    this.form.get('total_proveedores_externos')?.valueChanges.subscribe(() => {
      this.actualizarValidacionLugarAdquisicion();
    });

    if (this.isEditMode && this.tramiteAnexoProveeduriaOtraEntidadFederativa) {
      await this.loadData();
    }

    this.actualizarValidacionLugarAdquisicion();
  }

  private actualizarValidacionLugarAdquisicion(): void {
    const totalProveedores = this.form.get('total_proveedores_externos')?.value || 0;
    const lugarAdquisicionControl = this.form.get('lugar_adquisicion');

    if (totalProveedores > 0) {
      lugarAdquisicionControl?.addValidators([Validators.required]);
    } else {
      lugarAdquisicionControl?.removeValidators([Validators.required]);
    }
    lugarAdquisicionControl?.updateValueAndValidity();
  }

  private async loadData(): Promise<void> {
    if (!this.tramiteAnexoProveeduriaOtraEntidadFederativa) return;

    this.loading = true;
    this.form.patchValue(this.tramiteAnexoProveeduriaOtraEntidadFederativa);
    this.loading = false;
  }

  get f(): Record<string, AbstractControl> {
    return this.form.controls;
  }

  get mostrarLugarAdquisicion(): boolean {
    const totalProveedores = this.form.get('total_proveedores_externos')?.value || 0;
    return totalProveedores > 0;
  }

  async onSubmit(): Promise<void> {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const formData = this.form.value;
    let result: TramiteAnexoProveeduriaEntidadFederativa | undefined;

    if (this.isEditMode && this.tramiteAnexoProveeduriaOtraEntidadFederativa) {
      await this.tramiteAnexoProveeduriaEntidadFederativaService.update(this.tramiteAnexoProveeduriaOtraEntidadFederativa.id, formData);
      result = {
        ...this.tramiteAnexoProveeduriaOtraEntidadFederativa,
        ...formData
      };
    } else {
      result = await this.tramiteAnexoProveeduriaEntidadFederativaService.new(formData);
    }

    this.submitted = true;
    this.saved.emit(result);
    this.tramiteAnexoProveeduriaOtraEntidadFederativaChange.emit(result);
  }

  onCancel(): void {
    this.canceled.emit();
  }

  resetForm(): void {
    this.form.reset({
      tramite_id: this.tramiteId,
      total_proveedores_externos: 0,
      lugar_adquisicion: '',
    });
    this.submitted = false;
    this.actualizarValidacionLugarAdquisicion();
  }

  get titulo(): string {
    return this.isEditMode ? 'Editar' : 'Registrar';
  }

  get textoBoton(): string {
    return this.isEditMode ? 'Actualizar' : 'Guardar';
  }
}
