import { Component, EventEmitter, inject, Input, OnInit, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators, AbstractControl } from '@angular/forms';
import { TramiteAnexoDiversidadContratacionService } from '../../../../controllers/tramite-anexo-diversidad-contratacion.service';
import { TramiteAnexoDiversidadContratacion } from '../../../../models/tramite-anexo-diversidad-contratacion';
import { TramiteService } from '../../../../controllers/tramite.service';

@Component({
  selector: 'app-tramite-anexo-diversidad-contratacion-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './tramite-anexo-diversidad-contratacion-form.html',
  styleUrl: './tramite-anexo-diversidad-contratacion-form.css',
})
export class TramiteAnexoDiversidadContratacionForm implements OnInit {
  @Input() tramiteId?: number;
  @Input() tramiteAnexoDiversidadContratacion?: TramiteAnexoDiversidadContratacion;
  @Output() tramiteAnexoDiversidadContratacionChange = new EventEmitter<TramiteAnexoDiversidadContratacion>();
  @Output() saved = new EventEmitter<TramiteAnexoDiversidadContratacion>();
  @Output() canceled = new EventEmitter<void>();

  form: FormGroup = inject(FormBuilder).group({
    tramite_id: [null, Validators.required],
    num_personas_mayores: [0, [Validators.required, Validators.min(0)]],
    num_madres_solteras: [0, [Validators.required, Validators.min(0)]],
    num_personas_capacidades_diferentes: [0, [Validators.required, Validators.min(0)]],
    num_egresados_albergues: [0, [Validators.required, Validators.min(0)]],
    porcentaje_que_representan: [null, [Validators.min(0)]],
    areas_que_involucran: ['', Validators.required],
  });

  isEditMode = false;
  loading = false;
  submitted = false;

  private fb = inject(FormBuilder);
  private tramiteAnexoDiversidadContratacionService = inject(TramiteAnexoDiversidadContratacionService);
  private tramiteService = inject(TramiteService);

  async ngOnInit(): Promise<void> {
    if (!this.tramiteId) {
      const tramite = await this.tramiteService.getCurrentTramite(['anexoDiversidad']);
      this.tramiteAnexoDiversidadContratacion = tramite?.anexo_diversidad
      if (tramite) {
        this.tramiteId = tramite.id;
      }
    }

    this.isEditMode = !!this.tramiteAnexoDiversidadContratacion?.id;

    if (this.tramiteId) {
      this.form.patchValue({ tramite_id: this.tramiteId });
    }

    if (this.isEditMode && this.tramiteAnexoDiversidadContratacion) {
      await this.loadData();
    }
  }

  private async loadData(): Promise<void> {
    if (!this.tramiteAnexoDiversidadContratacion) return;

    this.loading = true;
    this.form.patchValue(this.tramiteAnexoDiversidadContratacion);
    this.loading = false;
  }

  get f(): Record<string, AbstractControl> {
    return this.form.controls;
  }

  async onSubmit(): Promise<void> {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const formData = this.form.value;
    let result: TramiteAnexoDiversidadContratacion | undefined;

    if (this.isEditMode && this.tramiteAnexoDiversidadContratacion) {
      await this.tramiteAnexoDiversidadContratacionService.update(this.tramiteAnexoDiversidadContratacion.id, formData);
      result = {
        ...this.tramiteAnexoDiversidadContratacion,
        ...formData
      };
    } else {
      result = await this.tramiteAnexoDiversidadContratacionService.new(formData);
    }

    this.submitted = true;
    this.saved.emit(result);
    this.tramiteAnexoDiversidadContratacionChange.emit(result);
  }

  onCancel(): void {
    this.canceled.emit();
  }

  resetForm(): void {
    this.form.reset({
      tramite_id: this.tramiteId,
      num_personas_mayores: 0,
      num_madres_solteras: 0,
      num_personas_capacidades_diferentes: 0,
      num_egresados_albergues: 0,
      porcentaje_que_representan: null,
      areas_que_involucran: '',
    });
    this.submitted = false;
  }

  get titulo(): string {
    return this.isEditMode ? 'Editar' : 'Registrar';
  }

  get textoBoton(): string {
    return this.isEditMode ? 'Actualizar' : 'Guardar';
  }
}
