import { Component, EventEmitter, inject, Input, Output, OnInit, OnChanges, SimpleChanges } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { DatosVinculacion } from '../../../../models/datos-vinculacion';
import { DatosVinculacionService } from '../../../../controllers/datos-vinculacion.service';

@Component({
  selector: 'app-empresa-vinculada-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './empresa-vinculada-form.html',
  styleUrl: './empresa-vinculada-form.css'
})
export class EmpresaVinculadaForm implements OnInit, OnChanges {
  form: FormGroup = inject(FormBuilder).group({
    tramite_id: [null, Validators.required],
    empresa_solicitante_id: [null, Validators.required],
    nombre_solicitante: ['', Validators.required],
    caracteristicas_vinculacion: ['', Validators.required]
  });

  isEditMode = false;
  loading = false;
  submitted = false;
  data?: DatosVinculacion;

  @Input() tramiteId?: number | null;
  @Input() empresaSolicitanteId?: number | null;
  @Input() datosVinculacion?: DatosVinculacion | null; 

  @Output() saved = new EventEmitter<DatosVinculacion>();
  @Output() canceled = new EventEmitter<void>();

  private servicio = inject(DatosVinculacionService);

  ngOnInit(): void {
    this.loading = true;
    if (this.tramiteId) {
      this.form.patchValue({ tramite_id: this.tramiteId });
    }

    if (this.empresaSolicitanteId) {
      this.form.patchValue({ empresa_solicitante_id: this.empresaSolicitanteId });
    }
 
    if (this.datosVinculacion) {
      this.data = this.datosVinculacion;
      this.isEditMode = true;
      this.form.patchValue(this.data);
    }
    this.loading = false;
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['empresaSolicitanteId'] && !changes['empresaSolicitanteId'].firstChange) {
      this.form.patchValue({ empresa_solicitante_id: changes['empresaSolicitanteId'].currentValue });
    }

    if (changes['datosVinculacion'] && !changes['datosVinculacion'].firstChange) {
      const nuevos = changes['datosVinculacion'].currentValue;
      if (nuevos) {
        this.data = nuevos;
        this.isEditMode = true;
        this.form.patchValue(nuevos);
      }
    }
  }

  async onSubmit(): Promise<void> {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    this.submitted = false;
    const formData = this.form.value;

    if (this.isEditMode && this.data) {
      const result = await this.servicio.update(this.data.id, formData,true);
      console.log("Resultado de la actualización:", result);
      if (result?.status) {
        this.data = { ...this.data, ...formData };
        this.submitted = true;
        this.saved.emit(this.data);
      }
    } else {
      const result = await this.servicio.new(formData,true);
            console.log("Resultado de la creación:", result);

      if (result?.id) {
        this.data = result;
        this.isEditMode = true;
        this.submitted = true;
        this.saved.emit(this.data);
      }
    }

  }

  isFieldInvalid(fieldName: string): boolean {
    const control = this.form.get(fieldName);
    return control ? control.invalid && (control.dirty || control.touched) : false;
  }

  hasFieldError(fieldName: string, errorType: string): boolean {
    const control = this.form.get(fieldName);
    return control ? control.hasError(errorType) : false;
  }
}