import { inject, Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../environments/environment';
import { StepSave } from '../models/step-save';

@Injectable({
  providedIn: 'root'
})
export class StepSaveService {
  private apiUrl = `${environment.api_url}/api/step-saves`;
  private http = inject(HttpClient);  

  /**
   * NOTE: This is a simplified example.
   * You should have a centralized way of getting the auth token,
   * likely from an authentication service after the user logs in.
   */
  private getAuthHeaders(): HttpHeaders {
    // TODO: Replace with your actual auth token retrieval logic
    const token = localStorage.getItem('authToken');
    return new HttpHeaders({
      'Authorization': `Bearer ${token}`,
      'Accept': 'application/json'
    });
  }

  /**
   * Saves the user's progress for a specific form section.
   * @param data The data to save.
   */
  saveStep(data: { tramite_id: number; anexo_slug: string; step: number; completed_steps: number[] }): Observable<StepSave> {
    return this.http.post<StepSave>(this.apiUrl, data, { headers: this.getAuthHeaders() });
  }

  /**
   * Retrieves the saved step for a user for a given form section.
   * @param tramite_id The ID of the tramite.
   * @param anexo_slug The slug of the anexo.
   */
  getStep(tramite_id: number, anexo_slug: string): Observable<StepSave> {
    const url = `${this.apiUrl}/${tramite_id}/${anexo_slug}`;
    return this.http.get<StepSave>(url, { headers: this.getAuthHeaders() });
  }
}
