import { Component, EventEmitter, inject, Input, OnInit, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators, AbstractControl } from '@angular/forms';
import { TramiteAnexoNivelSalarialNuevoEmpleoService } from '../../../../controllers/tramite-anexo-nivel-salarial-nuevo-empleo.service';
import { TramiteAnexoNivelSalarialNuevoEmpleo } from '../../../../models/tramite-anexo-nivel-salarial-nuevo-empleo';
import { TramiteService } from '../../../../controllers/tramite.service';

@Component({
  selector: 'app-tramite-anexop-nivel-salarial-nuevo-empleo-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './tramite-anexop-nivel-salarial-nuevo-empleo-form.html',
  styleUrl: './tramite-anexop-nivel-salarial-nuevo-empleo-form.css',
})
export class TramiteAnexopNivelSalarialNuevoEmpleoForm implements OnInit {
  @Input() tramiteId?: number;
  @Input() tramiteAnexoNivelSalarialNuevoEmpleo?: TramiteAnexoNivelSalarialNuevoEmpleo;
  @Output() tramiteAnexoNivelSalarialNuevoEmpleoChange = new EventEmitter<TramiteAnexoNivelSalarialNuevoEmpleo>();
  @Output() saved = new EventEmitter<TramiteAnexoNivelSalarialNuevoEmpleo>();
  @Output() canceled = new EventEmitter<void>();

  form: FormGroup = inject(FormBuilder).group({
    tramite_id: [null, Validators.required],
    num_empleos_a_generar: [0, [Validators.required, Validators.min(0)]],
    sueldo_promedio_diario_empleos_a_generar: [null, [Validators.min(0)]],
    num_veces_umas: [null, [Validators.min(0)]],
  });

  isEditMode = false;
  loading = false;
  submitted = false;

  private fb = inject(FormBuilder);
  private tramiteAnexoNivelSalarialNuevoEmpleoService = inject(TramiteAnexoNivelSalarialNuevoEmpleoService);
  private tramiteService = inject(TramiteService);

  async ngOnInit(): Promise<void> {
    if (!this.tramiteId) {
      const tramite = await this.tramiteService.getCurrentTramite(['anexoNivelSalarial']);
      this.tramiteAnexoNivelSalarialNuevoEmpleo = tramite?.anexo_nivel_salarial
      if (tramite) {
        this.tramiteId = tramite.id;
      }
    }

    this.isEditMode = !!this.tramiteAnexoNivelSalarialNuevoEmpleo?.id;


    if (this.tramiteId) {
      this.form.patchValue({ tramite_id: this.tramiteId });
    }

    if (this.isEditMode && this.tramiteAnexoNivelSalarialNuevoEmpleo) {
      await this.loadData();
    }
  }

  private async loadData(): Promise<void> {
    if (!this.tramiteAnexoNivelSalarialNuevoEmpleo) return;

    this.loading = true;
    this.form.patchValue(this.tramiteAnexoNivelSalarialNuevoEmpleo);
    this.loading = false;
  }

  get f(): Record<string, AbstractControl> {
    return this.form.controls;
  }

  async onSubmit(): Promise<void> {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const formData = this.form.value;
    let result: TramiteAnexoNivelSalarialNuevoEmpleo | undefined;

    if (this.isEditMode && this.tramiteAnexoNivelSalarialNuevoEmpleo) {
      await this.tramiteAnexoNivelSalarialNuevoEmpleoService.update(this.tramiteAnexoNivelSalarialNuevoEmpleo.id, formData);
      result = {
        ...this.tramiteAnexoNivelSalarialNuevoEmpleo,
        ...formData
      };
    } else {
      result = await this.tramiteAnexoNivelSalarialNuevoEmpleoService.new(formData);
    }

    this.submitted = true;
    this.saved.emit(result);
    this.tramiteAnexoNivelSalarialNuevoEmpleoChange.emit(result);
  }

  onCancel(): void {
    this.canceled.emit();
  }

  resetForm(): void {
    this.form.reset({
      tramite_id: this.tramiteId,
      num_empleos_a_generar: 0,
      sueldo_promedio_diario_empleos_a_generar: null,
      num_veces_umas: null,
    });
    this.submitted = false;
  }

  get titulo(): string {
    return this.isEditMode ? 'Editar' : 'Registrar';
  }

  get textoBoton(): string {
    return this.isEditMode ? 'Actualizar' : 'Guardar';
  }
}
